CREATE TYPE "OrderStatus" AS ENUM ('DRAFT','CONFIRMED','COMPLETED','CANCELLED');
CREATE TYPE "OrderPaymentStatus" AS ENUM ('UNPAID','PAYMENT_REQUESTED','PARTIALLY_PAID','FULLY_PAID');
CREATE TYPE "OrderPaymentMethod" AS ENUM ('PAYPAL','CASH','BANK_TRANSFER','OTHER');
CREATE TYPE "PaymentRecordStatus" AS ENUM ('PENDING','PAID','FAILED','CANCELLED','REFUNDED');
CREATE TABLE "ConciergeOrder" ("id" TEXT NOT NULL,"orderNumber" TEXT NOT NULL,"contactRequestId" TEXT,"individualId" TEXT,"clientFirstName" TEXT NOT NULL,"clientLastName" TEXT NOT NULL,"clientEmail" TEXT NOT NULL,"clientPhone" TEXT,"clientLanguage" TEXT NOT NULL DEFAULT 'en',"currency" TEXT NOT NULL DEFAULT 'EUR',"status" "OrderStatus" NOT NULL DEFAULT 'DRAFT',"paymentStatus" "OrderPaymentStatus" NOT NULL DEFAULT 'UNPAID',"totalAmount" DECIMAL(12,2) NOT NULL,"paidAmount" DECIMAL(12,2) NOT NULL DEFAULT 0,"remainingAmount" DECIMAL(12,2) NOT NULL,"notes" TEXT,"createdDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdBy" TEXT,"updatedDate" TIMESTAMP(3) NOT NULL,"updatedBy" TEXT,CONSTRAINT "ConciergeOrder_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ConciergeOrderItem" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"productType" TEXT NOT NULL,"productId" TEXT,"productName" TEXT NOT NULL,"planId" TEXT,"planName" TEXT,"optionId" TEXT,"optionName" TEXT,"startDate" TIMESTAMP(3),"endDate" TIMESTAMP(3),"quantity" INTEGER NOT NULL DEFAULT 1,"unitPrice" DECIMAL(12,2) NOT NULL,"totalPrice" DECIMAL(12,2) NOT NULL,"notes" TEXT,"createdDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedDate" TIMESTAMP(3) NOT NULL,CONSTRAINT "ConciergeOrderItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ConciergeOrderPayment" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"amount" DECIMAL(12,2) NOT NULL,"currency" TEXT NOT NULL DEFAULT 'EUR',"method" "OrderPaymentMethod" NOT NULL,"status" "PaymentRecordStatus" NOT NULL DEFAULT 'PENDING',"publicToken" TEXT,"paypalOrderId" TEXT,"paypalCaptureId" TEXT,"checkoutUrl" TEXT,"checkoutExpiresAt" TIMESTAMP(3),"emailSentAt" TIMESTAMP(3),"paidAt" TIMESTAMP(3),"recordedBy" TEXT,"notes" TEXT,"createdDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedDate" TIMESTAMP(3) NOT NULL,CONSTRAINT "ConciergeOrderPayment_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ConciergeOrder_orderNumber_key" ON "ConciergeOrder"("orderNumber"); CREATE INDEX "ConciergeOrder_contactRequestId_idx" ON "ConciergeOrder"("contactRequestId"); CREATE INDEX "ConciergeOrder_individualId_idx" ON "ConciergeOrder"("individualId"); CREATE INDEX "ConciergeOrder_status_paymentStatus_idx" ON "ConciergeOrder"("status","paymentStatus"); CREATE INDEX "ConciergeOrder_clientEmail_idx" ON "ConciergeOrder"("clientEmail");
CREATE INDEX "ConciergeOrderItem_orderId_idx" ON "ConciergeOrderItem"("orderId"); CREATE INDEX "ConciergeOrderItem_productType_productId_idx" ON "ConciergeOrderItem"("productType","productId");
CREATE UNIQUE INDEX "ConciergeOrderPayment_publicToken_key" ON "ConciergeOrderPayment"("publicToken"); CREATE UNIQUE INDEX "ConciergeOrderPayment_paypalOrderId_key" ON "ConciergeOrderPayment"("paypalOrderId"); CREATE UNIQUE INDEX "ConciergeOrderPayment_paypalCaptureId_key" ON "ConciergeOrderPayment"("paypalCaptureId"); CREATE INDEX "ConciergeOrderPayment_orderId_status_idx" ON "ConciergeOrderPayment"("orderId","status");
ALTER TABLE "ConciergeOrder" ADD CONSTRAINT "ConciergeOrder_contactRequestId_fkey" FOREIGN KEY ("contactRequestId") REFERENCES "ContactRequest"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "ConciergeOrder" ADD CONSTRAINT "ConciergeOrder_individualId_fkey" FOREIGN KEY ("individualId") REFERENCES "Individual"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "ConciergeOrderItem" ADD CONSTRAINT "ConciergeOrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "ConciergeOrder"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ConciergeOrderPayment" ADD CONSTRAINT "ConciergeOrderPayment_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "ConciergeOrder"("id") ON DELETE CASCADE ON UPDATE CASCADE;
